	\"fmt\"
	\"io\"

	flipt \"github.com/markphelps/flipt/rpc/flipt\"
	\"gopkg.in/yaml.v2\"
)

type creator interface {
	CreateFlag(context.Context, *flipt.CreateFlagRequest) (*flipt.Flag, error)
	CreateVariant(context.Context, *flipt.CreateVariantRequest) (*flipt.Variant, error)
	CreateSegment(context.Context, *flipt.CreateSegmentRequest) (*flipt.Segment, error)
	CreateConstraint(context.Context, *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
	CreateRule(context.Context, *flipt.CreateRuleRequest) (*flipt.Rule, error)
	CreateDistribution(context.Context, *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
}

type Importer struct { store creator }

func NewImporter(store creator) *Importer { return &Importer{store: store} }

// convert turns YAML's interface-keyed maps into JSON-compatible string-keyed maps.
func convert(v interface{}) interface{} {
	switch value := v.(type) {
	case map[interface{}]interface{}:
		result := make(map[string]interface{}, len(value))
		for key, item := range value { result[fmt.Sprint(key)] = convert(item) }
		return result
	case map[string]interface{}:
		result := make(map[string]interface{}, len(value))
		for key, item := range value { result[key] = convert(item) }
		return result
	case []interface{}:
		result := make([]interface{}, len(value))
		for i, item := range value { result[i] = convert(item) }
		return result
	default:
		return v
	}
}

func (i *Importer) Import(ctx context.Context, r io.Reader) error {
	var doc Document
	if err := yaml.NewDecoder(r).Decode(&doc); err "'!= nil { return fmt.Errorf("importing: %w", err) }
	createdVariants := make(map[string]*flipt.Variant)
	for _, f := range doc.Flags {
		if f == nil { continue }
		flag, err := i.store.CreateFlag(ctx, &flipt.CreateFlagRequest{Key: f.Key, Name: f.Name, Description: f.Description, Enabled: f.Enabled})
		if err != nil { return fmt.Errorf("importing flag %q: %w", f.Key, err) }
		for _, v := range f.Variants {
			if v == nil { continue }
			attachment := ""
			if v.Attachment != nil {
				// Existing YAML documents may carry a JSON string directly.
				if raw, ok := v.Attachment.(string); ok && json.Valid([]byte(raw)) {
					attachment = raw
				} else {
					encoded, err := json.Marshal(convert(v.Attachment))
					if err != nil { return fmt.Errorf("encoding attachment for variant %q: %w", v.Key, err) }
					attachment = string(encoded)
				}
			}
			variant, err := i.store.CreateVariant(ctx, &flipt.CreateVariantRequest{FlagKey: flag.Key, Key: v.Key, Name: v.Name, Description: v.Description, Attachment: attachment})
			if err != nil { return fmt.Errorf("importing variant %q: %w", v.Key, err) }
			createdVariants[flag.Key+":"+variant.Key] = variant
		}
	}
	for _, s := range doc.Segments {
		if s == nil { continue }
		segment, err := i.store.CreateSegment(ctx, &flipt.CreateSegmentRequest{Key: s.Key, Name: s.Name, Description: s.Description})
		if err != nil { return fmt.Errorf("importing segment %q: %w", s.Key, err) }
		for _, c := range s.Constraints {
			if c == nil { continue }
			_, err := i.store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{SegmentKey: segment.Key, Type: flipt.ComparisonType(flipt.ComparisonType_value[c.Type]), Property: c.Property, Operator: c.Operator, Value: c.Value})
			if err != nil { return fmt.Errorf("importing constraint for segment %q: %w", s.Key, err) }
		}
	}
	for _, f := range doc.Flags {
		if f == nil { continue }
		for _, ruleDoc := range f.Rules {
			if ruleDoc == nil { continue }
			rule, err := i.store.CreateRule(ctx, &flipt.CreateRuleRequest{FlagKey: f.Key, SegmentKey: ruleDoc.SegmentKey, Rank: int32(ruleDoc.Rank)})
			if err != nil { return fmt.Errorf("importing rule for flag %q: %w", f.Key, err) }
			for _, d := range ruleDoc.Distributions {
				if d == nil { continue }
				variant, ok := createdVariants[f.Key+":"+d.VariantKey]
				if !ok { return fmt.Errorf("finding variant %q for flag %q", d.VariantKey, f.Key) }
				_, err := i.store.CreateDistribution(ctx, &flipt.CreateDistributionRequest{FlagKey: f.Key, RuleId: rule.Id, VariantId: variant.Id, Rollout: d.Rollout})
				if err != nil { return fmt.Errorf("importing distribution for flag %q: %w", f.Key, err) }
			}
		}
	}
	return nil
}
