type listStore struct {
	flags []*flipt.Flag
	rules []*flipt.Rule
	segments []*flipt.Segment
}
func (s *listStore) ListFlags(_ context.Context, opts ...storage.QueryOption) ([]*flipt.Flag, error) {
	p := storage.QueryParams{}; for _, o := range opts { o(&p) }; if p.Offset >= uint64(len(s.flags)) { return nil,nil }; end:=p.Offset+p.Limit; if end>uint64(len(s.flags)){end=uint64(len(s.flags))}; return s.flags[p.Offset:end],nil
}
func (s *listStore) ListRules(_ context.Context, _ string, opts ...storage.QueryOption) ([]*flipt.Rule,error) {
	p:=storage.QueryParams{}; for _,o:=range opts{o(&p)}; if p.Offset>=uint64(len(s.rules)){return nil,nil}; end:=p.Offset+p.Limit; if end>uint64(len(s.rules)){end=uint64(len(s.rules))};return s.rules[p.Offset:end],nil
}
func (s *listStore) ListSegments(_ context.Context, opts ...storage.QueryOption) ([]*flipt.Segment,error) {
	p:=storage.QueryParams{}; for _,o:=range opts{o(&p)}; if p.Offset>=uint64(len(s.segments)){return nil,nil};end:=p.Offset+p.Limit;if end>uint64(len(s.segments)){end=uint64(len(s.segments))};return s.segments[p.Offset:end],nil
}

type createStore struct {
	flags []*flipt.CreateFlagRequest
	variants []*flipt.CreateVariantRequest
	segments []*flipt.CreateSegmentRequest
	constraints []*flipt.CreateConstraintRequest
	rules []*flipt.CreateRuleRequest
	distributions []*flipt.CreateDistributionRequest
}
func(s *createStore) CreateFlag(_ context.Context,r *flipt.CreateFlagRequest)(*flipt.Flag,error){s.flags=append(s.flags,r);return &flipt.Flag{Key:r.Key},nil}
func(s *createStore) CreateVariant(_ context.Context,r *flipt.CreateVariantRequest)(*flipt.Variant,error){s.variants=append(s.variants,r);return &flipt.Variant{Id:\"variant-id\",Key:r.Key},nil}
func(s *createStore) CreateSegment(_ context.Context,r *flipt.CreateSegmentRequest)(*flipt.Segment,error){s.segments=append(s.segments,r);return &flipt.Segment{Key:r.Key},nil}
func(s *createStore) CreateConstraint(_ context.Context,r *flipt.CreateConstraintRequest)(*flipt.Constraint,error){s.constraints=append(s.constraints,r);return &flipt.Constraint{},nil}
func(s *createStore) CreateRule(_ context.Context,r *flipt.CreateRuleRequest)(*flipt.Rule,error){s.rules=append(s.rules,r);return &flipt.Rule{Id:\"rule-id\"},nil}
func(s *createStore) CreateDistribution(_ context.Context,r *flipt.CreateDistributionRequest)(*flipt.Distribution,error){s.distributions=append(s.distributions,r);return &flipt.Distribution{},nil}

func TestExportImportAttachmentsAndHierarchy(t *testing.T) {
	attachment := "'`{"nested":{"items":[true,4,null,{"label":"hello"}]},"empty":[],"number":3.5}`
	listed:=&listStore{
		flags:[]*flipt.Flag{{Key:"feature",Name:"Feature",Enabled:true,Variants:[]*flipt.Variant{{Id:"id-1",Key:"blue",Attachment:attachment},{Id:"id-2",Key:"plain"}}}},
		rules:[]*flipt.Rule{{SegmentKey:"users",Rank:1,Distributions:[]*flipt.Distribution{{VariantId:"id-1",Rollout:50}}}},
		segments:[]*flipt.Segment{{Key:"users",Constraints:[]*flipt.Constraint{{Type:flipt.ComparisonType(1),Property:"region",Operator:"eq",Value:"us"}}}},
	}
	var output bytes.Buffer
	if err:=NewExporter(listed).Export(context.Background(),&output);err!=nil{t.Fatal(err)}
	var doc Document
	if err:=yaml.Unmarshal(output.Bytes(),&doc);err!=nil{t.Fatal(err)}
	if _,ok:=doc.Flags[0].Variants[0].Attachment.(map[interface{}]interface{});!ok{t.Fatalf("attachment is not a YAML map: %s",output.String())}
	if strings.Contains(output.String(),"attachment: '"'{\") {t.Fatalf(\"attachment emitted as JSON string: %s\",output.String())}
	if len(doc.Flags[0].Rules)"'!=1||len(doc.Segments)!=1||len(doc.Segments[0].Constraints)!=1{t.Fatalf("hierarchy missing: %s",output.String())}
	created:=&createStore{}
	if err:=NewImporter(created).Import(context.Background(),bytes.NewReader(output.Bytes()));err!=nil{t.Fatal(err)}
	if len(created.flags)!=1||len(created.variants)!=2||len(created.segments)!=1||len(created.constraints)!=1||len(created.rules)!=1||len(created.distributions)!=1{t.Fatalf("entities missing: %+v",created)}
	var got,want interface{}
	if err:=json.Unmarshal([]byte(created.variants[0].Attachment),&got);err!=nil{t.Fatal(err)}
	if err:=json.Unmarshal([]byte(attachment),&want);err!=nil{t.Fatal(err)}
	if !reflectDeepEqual(got,want){t.Fatalf("attachment changed: %#v != %#v",got,want)}
	if created.variants[1].Attachment!=""{t.Fatalf("missing attachment became %q",created.variants[1].Attachment)}
	if created.distributions[0].VariantId!="variant-id"||created.distributions[0].RuleId!="rule-id"{t.Fatal("distribution references lost")}
}

